/**
 * RealWorld error payloads always look like `{ "errors": { "<field>": ["<message>"] } }`.
 * Every failure path in this API raises an `ApiError` so the Fastify error handler can
 * serialise it in exactly that shape.
 */
export class ApiError extends Error {
  constructor(
    readonly statusCode: number,
    readonly errors: Record<string, string[]>,
  ) {
    super(`API error ${statusCode}`)
    this.name = 'ApiError'
  }
}

export const missingToken = () => new ApiError(401, { token: ['is missing'] })
export const invalidToken = () => new ApiError(401, { token: ['is invalid'] })
export const invalidCredentials = () => new ApiError(401, { credentials: ['invalid'] })

export const notFound = (resource: string) => new ApiError(404, { [resource]: ['not found'] })
export const forbidden = (resource: string) => new ApiError(403, { [resource]: ['forbidden'] })
export const alreadyTaken = (field: string) =>
  new ApiError(409, { [field]: ['has already been taken'] })
export const unprocessable = (errors: Record<string, string[]>) => new ApiError(422, errors)

