import { unprocessable } from './errors.js'

export const BLANK = "can't be blank"
export const INVALID = 'is invalid'
export const tooShort = (min: number) => `is too short (minimum is ${min} characters)`

export const MIN_PASSWORD_LENGTH = 8

type Json = Record<string, unknown>

/** Accumulates per-field messages and turns them into a single 422 response. */
export class FieldErrors {
  private readonly errors: Record<string, string[]> = {}

  add(field: string, message: string): this {
    ;(this.errors[field] ??= []).push(message)
    return this
  }

  get isEmpty(): boolean {
    return Object.keys(this.errors).length === 0
  }

  throwIfAny(): void {
    if (!this.isEmpty) throw unprocessable(this.errors)
  }
}

/**
 * Unwraps the single-key envelope every RealWorld endpoint uses (`{ "user": {...} }`).
 * A missing or non-object envelope is reported as a blank error on the envelope itself.
 */
export function envelope(body: unknown, key: string): Json {
  const root = isPlainObject(body) ? body[key] : undefined
  if (!isPlainObject(root)) throw unprocessable({ [key]: [BLANK] })
  return root
}

export function isPlainObject(value: unknown): value is Json {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

/** Required on create: absent, null, empty or whitespace-only all count as blank. */
export function requiredString(
  source: Json,
  field: string,
  errors: FieldErrors,
): string | undefined {
  const value = source[field]
  if (value === undefined || value === null || value === '') {
    errors.add(field, BLANK)
    return undefined
  }
  if (typeof value !== 'string') {
    errors.add(field, INVALID)
    return undefined
  }
  if (value.trim() === '') {
    errors.add(field, BLANK)
    return undefined
  }
  return value
}

/**
 * Optional on update but never nullable: leaving the key out is fine, providing it
 * blank or null is not. Returns `undefined` when the key was absent.
 */
export function optionalNonBlankString(
  source: Json,
  field: string,
  errors: FieldErrors,
): string | undefined {
  if (!(field in source)) return undefined
  return requiredString(source, field, errors)
}

/**
 * Optional and nullable (bio, image). An empty string is normalised to `null` so the
 * API never reports an empty string back to clients.
 */
export function optionalNullableString(
  source: Json,
  field: string,
  errors: FieldErrors,
): { present: boolean; value: string | null } {
  if (!(field in source)) return { present: false, value: null }
  const value = source[field]
  if (value === null || value === '') return { present: true, value: null }
  if (typeof value !== 'string') {
    errors.add(field, INVALID)
    return { present: false, value: null }
  }
  return { present: true, value }
}

/** Applies the NIST 800-63B length rules: at least 8 characters, long ones accepted as-is. */
export function validatePassword(password: string | undefined, errors: FieldErrors): void {
  if (password !== undefined && password.length < MIN_PASSWORD_LENGTH) {
    errors.add('password', tooShort(MIN_PASSWORD_LENGTH))
  }
}

/**
 * `tagList` is optional, but when present it must be an array of strings — an explicit
 * `null` is rejected rather than silently treated as "clear all tags".
 */
export function optionalTagList(
  source: Json,
  errors: FieldErrors,
): { present: boolean; value: string[] } {
  if (!('tagList' in source)) return { present: false, value: [] }
  const value = source['tagList']
  if (!Array.isArray(value) || value.some((tag) => typeof tag !== 'string')) {
    errors.add('tagList', INVALID)
    return { present: false, value: [] }
  }
  const tags = (value as string[]).map((tag) => tag.trim()).filter((tag) => tag !== '')
  return { present: true, value: [...new Set(tags)].sort() }
}

