import jwt from 'jsonwebtoken'

const SECRET = process.env['JWT_SECRET'] ?? 'realworld-development-secret'
const EXPIRES_IN = '30d'

export interface TokenPayload {
  id: number
  username: string
}

export function signToken(payload: TokenPayload): string {
  return jwt.sign(payload, SECRET, { expiresIn: EXPIRES_IN })
}

/** Returns the payload for a valid token, or `null` for anything malformed or expired. */
export function verifyToken(token: string): TokenPayload | null {
  try {
    const decoded = jwt.verify(token, SECRET)
    if (typeof decoded === 'string' || typeof decoded.id !== 'number') return null
    return { id: decoded.id, username: String(decoded['username']) }
  } catch {
    return null
  }
}

