import type { FastifyPluginAsync, FastifyRequest, preHandlerHookHandler } from 'fastify'
import fp from 'fastify-plugin'
import { invalidToken, missingToken } from '../lib/errors.js'
import { verifyToken, type TokenPayload } from '../lib/token.js'

declare module 'fastify' {
  interface FastifyRequest {
    /** Payload of a valid `Authorization` header, or `null` for anonymous requests. */
    auth: TokenPayload | null
  }
}

// RealWorld standardised on `Token <jwt>`; `Bearer` is accepted too since many
// clients and proxies default to it.
const SCHEME = /^(Token|Bearer)\s+(.+)$/i

const plugin: FastifyPluginAsync = async (app) => {
  app.decorateRequest('auth', null)

  app.addHook('onRequest', async (request) => {
    const header = request.headers.authorization
    if (!header) return

    const match = SCHEME.exec(header.trim())
    if (!match) throw invalidToken()

    const payload = verifyToken(match[2]!)
    if (!payload) throw invalidToken()

    request.auth = payload
  })
}

export const authPlugin = fp(plugin, { name: 'auth' })

/** Route guard for endpoints that reject anonymous callers with 401. */
export const requireAuth: preHandlerHookHandler = async (request) => {
  if (!request.auth) throw missingToken()
}

/** Narrows `request.auth` for handlers already protected by {@link requireAuth}. */
export function currentUserId(request: FastifyRequest): number {
  if (!request.auth) throw missingToken()
  return request.auth.id
}

