import type { Prisma } from '@prisma/client'
import { signToken } from './token.js'

/**
 * Shared Prisma selections. Article and comment payloads always embed an author
 * profile, whose `following` flag depends on the caller, so every query loads the
 * viewer's follow rows alongside the record.
 */
export const authorSelect = (viewerId: number) =>
  ({
    select: {
      username: true,
      bio: true,
      image: true,
      followers: { where: { followerId: viewerId }, select: { followerId: true } },
    },
  }) satisfies Prisma.UserDefaultArgs

export const articleInclude = (viewerId: number) =>
  ({
    author: authorSelect(viewerId),
    tags: { select: { tag: { select: { name: true } } } },
    favorites: { where: { userId: viewerId }, select: { userId: true } },
    _count: { select: { favorites: true } },
  }) satisfies Prisma.ArticleInclude

export const commentInclude = (viewerId: number) =>
  ({
    author: authorSelect(viewerId),
  }) satisfies Prisma.CommentInclude

// Records shaped by the selections above. Kept structural so the presenters accept
// any query that includes at least these fields.
interface AuthorRecord {
  username: string
  bio: string | null
  image: string | null
  followers: unknown[]
}

interface UserRecord {
  id: number
  email: string
  username: string
  bio: string | null
  image: string | null
}

interface ArticleRecord {
  slug: string
  title: string
  description: string
  body: string
  createdAt: Date
  updatedAt: Date
  author: AuthorRecord
  tags: { tag: { name: string } }[]
  favorites: unknown[]
  _count: { favorites: number }
}

interface CommentRecord {
  id: number
  body: string
  createdAt: Date
  updatedAt: Date
  author: AuthorRecord
}

export interface Profile {
  username: string
  bio: string | null
  image: string | null
  following: boolean
}

export function toProfile(author: AuthorRecord): Profile {
  return {
    username: author.username,
    bio: author.bio,
    image: author.image,
    following: author.followers.length > 0,
  }
}

/** The authenticated-user payload, which carries a freshly minted token. */
export function toUser(user: UserRecord) {
  return {
    email: user.email,
    token: signToken({ id: user.id, username: user.username }),
    username: user.username,
    bio: user.bio,
    image: user.image,
  }
}

/**
 * Article view. List endpoints omit `body` entirely — the spec asserts the key is
 * absent rather than null — so it is only attached when `withBody` is set.
 */
export function toArticle(article: ArticleRecord, withBody: boolean) {
  const base = {
    slug: article.slug,
    title: article.title,
    description: article.description,
    tagList: article.tags.map((link) => link.tag.name).sort(),
    createdAt: article.createdAt.toISOString(),
    updatedAt: article.updatedAt.toISOString(),
    favorited: article.favorites.length > 0,
    favoritesCount: article._count.favorites,
    author: toProfile(article.author),
  }

  return withBody ? { ...base, body: article.body } : base
}

export function toComment(comment: CommentRecord) {
  return {
    id: comment.id,
    createdAt: comment.createdAt.toISOString(),
    updatedAt: comment.updatedAt.toISOString(),
    body: comment.body,
    author: toProfile(comment.author),
  }
}

