import type { FastifyPluginAsync } from 'fastify'
import { alreadyTaken, invalidCredentials } from '../lib/errors.js'
import { hashPassword, verifyPassword } from '../lib/password.js'
import { toUser } from '../lib/presenters.js'
import { prisma } from '../lib/prisma.js'
import {
  envelope,
  FieldErrors,
  optionalNonBlankString,
  optionalNullableString,
  requiredString,
  validatePassword,
} from '../lib/validation.js'
import { currentUserId, requireAuth } from '../plugins/auth.js'

/** Rejects a username/email that another account already owns. */
async function assertAvailable(
  fields: { username?: string | undefined; email?: string | undefined },
  excludeUserId?: number,
): Promise<void> {
  if (fields.username !== undefined) {
    const owner = await prisma.user.findUnique({ where: { username: fields.username } })
    if (owner && owner.id !== excludeUserId) throw alreadyTaken('username')
  }
  if (fields.email !== undefined) {
    const owner = await prisma.user.findUnique({ where: { email: fields.email } })
    if (owner && owner.id !== excludeUserId) throw alreadyTaken('email')
  }
}

export const userRoutes: FastifyPluginAsync = async (app) => {
  // Registration
  app.post('/users', async (request, reply) => {
    const input = envelope(request.body, 'user')
    const errors = new FieldErrors()

    const username = requiredString(input, 'username', errors)
    const email = requiredString(input, 'email', errors)
    const password = requiredString(input, 'password', errors)
    validatePassword(password, errors)
    errors.throwIfAny()

    await assertAvailable({ username, email })

    const user = await prisma.user.create({
      data: {
        username: username!,
        email: email!,
        passwordHash: await hashPassword(password!),
      },
    })

    return reply.code(201).send({ user: toUser(user) })
  })

  // Login
  app.post('/users/login', async (request) => {
    const input = envelope(request.body, 'user')
    const errors = new FieldErrors()

    const email = requiredString(input, 'email', errors)
    const password = requiredString(input, 'password', errors)
    errors.throwIfAny()

    const user = await prisma.user.findUnique({ where: { email: email! } })
    if (!user || !(await verifyPassword(password!, user.passwordHash))) {
      throw invalidCredentials()
    }

    return { user: toUser(user) }
  })

  // Current user
  app.get('/user', { preHandler: requireAuth }, async (request) => {
    const user = await prisma.user.findUniqueOrThrow({ where: { id: currentUserId(request) } })
    return { user: toUser(user) }
  })

  // Update current user
  app.put('/user', { preHandler: requireAuth }, async (request) => {
    const userId = currentUserId(request)
    const input = envelope(request.body, 'user')
    const errors = new FieldErrors()

    const username = optionalNonBlankString(input, 'username', errors)
    const email = optionalNonBlankString(input, 'email', errors)
    const password = optionalNonBlankString(input, 'password', errors)
    validatePassword(password, errors)
    const bio = optionalNullableString(input, 'bio', errors)
    const image = optionalNullableString(input, 'image', errors)
    errors.throwIfAny()

    await assertAvailable({ username, email }, userId)

    const user = await prisma.user.update({
      where: { id: userId },
      data: {
        ...(username !== undefined && { username }),
        ...(email !== undefined && { email }),
        ...(password !== undefined && { passwordHash: await hashPassword(password) }),
        ...(bio.present && { bio: bio.value }),
        ...(image.present && { image: image.value }),
      },
    })

    return { user: toUser(user) }
  })
}

