import type { FastifyPluginAsync, FastifyRequest } from 'fastify'
import { notFound } from '../lib/errors.js'
import { authorSelect, toProfile } from '../lib/presenters.js'
import { prisma } from '../lib/prisma.js'
import { currentUserId, requireAuth } from '../plugins/auth.js'

interface UsernameParams {
  username: string
}

const ANONYMOUS = -1

/** Loads a profile as seen by `viewerId`, or raises the spec's 404 payload. */
async function loadProfile(username: string, viewerId: number) {
  const user = await prisma.user.findUnique({
    where: { username },
    ...authorSelect(viewerId),
  })
  if (!user) throw notFound('profile')
  return toProfile(user)
}

export const profileRoutes: FastifyPluginAsync = async (app) => {
  app.get<{ Params: UsernameParams }>('/profiles/:username', async (request) => {
    const viewerId = request.auth?.id ?? ANONYMOUS
    return { profile: await loadProfile(request.params.username, viewerId) }
  })

  app.post<{ Params: UsernameParams }>(
    '/profiles/:username/follow',
    { preHandler: requireAuth },
    async (request) => followRoute(request, true),
  )

  app.delete<{ Params: UsernameParams }>(
    '/profiles/:username/follow',
    { preHandler: requireAuth },
    async (request) => followRoute(request, false),
  )
}

async function followRoute(
  request: FastifyRequest<{ Params: UsernameParams }>,
  shouldFollow: boolean,
) {
  const followerId = currentUserId(request)
  const target = await prisma.user.findUnique({ where: { username: request.params.username } })
  if (!target) throw notFound('profile')

  const key = { followerId_followeeId: { followerId, followeeId: target.id } }
  if (shouldFollow) {
    // Following yourself is a no-op rather than an error: the follow table has no
    // meaningful row for it and the spec defines no failure case.
    if (target.id !== followerId) {
      await prisma.follow.upsert({
        where: key,
        create: { followerId, followeeId: target.id },
        update: {},
      })
    }
  } else {
    await prisma.follow.deleteMany({ where: { followerId, followeeId: target.id } })
  }

  return { profile: await loadProfile(request.params.username, followerId) }
}

