import type { FastifyPluginAsync } from 'fastify'
import { forbidden, notFound } from '../lib/errors.js'
import { commentInclude, toComment } from '../lib/presenters.js'
import { prisma } from '../lib/prisma.js'
import { envelope, FieldErrors, requiredString } from '../lib/validation.js'
import { currentUserId, requireAuth } from '../plugins/auth.js'

interface SlugParams {
  slug: string
}

interface CommentParams extends SlugParams {
  id: string
}

const ANONYMOUS = -1

/** Resolves the article a comment route hangs off, raising 404 before anything else. */
async function articleIdFromSlug(slug: string): Promise<number> {
  const article = await prisma.article.findUnique({ where: { slug }, select: { id: true } })
  if (!article) throw notFound('article')
  return article.id
}

export const commentRoutes: FastifyPluginAsync = async (app) => {
  app.get<{ Params: SlugParams }>('/articles/:slug/comments', async (request) => {
    const articleId = await articleIdFromSlug(request.params.slug)
    const viewerId = request.auth?.id ?? ANONYMOUS

    const comments = await prisma.comment.findMany({
      where: { articleId },
      orderBy: { id: 'asc' },
      include: commentInclude(viewerId),
    })

    return { comments: comments.map(toComment) }
  })

  app.post<{ Params: SlugParams }>(
    '/articles/:slug/comments',
    { preHandler: requireAuth },
    async (request, reply) => {
      const userId = currentUserId(request)
      const articleId = await articleIdFromSlug(request.params.slug)

      const input = envelope(request.body, 'comment')
      const errors = new FieldErrors()
      const body = requiredString(input, 'body', errors)
      errors.throwIfAny()

      const comment = await prisma.comment.create({
        data: { body: body!, articleId, authorId: userId },
        include: commentInclude(userId),
      })

      return reply.code(201).send({ comment: toComment(comment) })
    },
  )

  app.delete<{ Params: CommentParams }>(
    '/articles/:slug/comments/:id',
    { preHandler: requireAuth },
    async (request, reply) => {
      const userId = currentUserId(request)
      const articleId = await articleIdFromSlug(request.params.slug)

      const commentId = Number.parseInt(request.params.id, 10)
      if (Number.isNaN(commentId)) throw notFound('comment')

      const comment = await prisma.comment.findFirst({
        where: { id: commentId, articleId },
        select: { id: true, authorId: true },
      })
      if (!comment) throw notFound('comment')
      if (comment.authorId !== userId) throw forbidden('comment')

      await prisma.comment.delete({ where: { id: comment.id } })
      return reply.code(204).send()
    },
  )
}

