import type { Prisma } from '@prisma/client'
import type { FastifyPluginAsync, FastifyRequest } from 'fastify'
import { forbidden, notFound } from '../lib/errors.js'
import { articleInclude, toArticle } from '../lib/presenters.js'
import { prisma } from '../lib/prisma.js'
import { slugify } from '../lib/slug.js'
import {
  envelope,
  FieldErrors,
  optionalNonBlankString,
  optionalTagList,
  requiredString,
} from '../lib/validation.js'
import { currentUserId, requireAuth } from '../plugins/auth.js'

interface SlugParams {
  slug: string
}

interface ListQuery {
  tag?: string
  author?: string
  favorited?: string
  limit?: string
  offset?: string
}

const ANONYMOUS = -1
const DEFAULT_LIMIT = 20
const MAX_LIMIT = 100

// Newest first, with the id as a tiebreaker so articles created within the same
// millisecond still come back in a stable, insertion-reversed order.
const NEWEST_FIRST: Prisma.ArticleOrderByWithRelationInput[] = [{ createdAt: 'desc' }, { id: 'desc' }]

function parseBound(raw: string | undefined, fallback: number, max: number): number {
  const value = Number.parseInt(raw ?? '', 10)
  if (Number.isNaN(value) || value < 0) return fallback
  return Math.min(value, max)
}

/**
 * Runs a paginated article query. `articlesCount` reports how many articles match the
 * filter overall, not how many fit on the requested page.
 */
async function listArticles(where: Prisma.ArticleWhereInput, query: ListQuery, viewerId: number) {
  const limit = parseBound(query.limit, DEFAULT_LIMIT, MAX_LIMIT)
  const offset = parseBound(query.offset, 0, Number.MAX_SAFE_INTEGER)

  const [articles, articlesCount] = await Promise.all([
    prisma.article.findMany({
      where,
      orderBy: NEWEST_FIRST,
      skip: offset,
      take: limit,
      include: articleInclude(viewerId),
    }),
    prisma.article.count({ where }),
  ])

  return { articles: articles.map((article) => toArticle(article, false)), articlesCount }
}

/** Loads an article by slug for presentation, raising the spec's 404 payload if absent. */
async function loadArticle(slug: string, viewerId: number) {
  const article = await prisma.article.findUnique({
    where: { slug },
    include: articleInclude(viewerId),
  })
  if (!article) throw notFound('article')
  return article
}

/** Loads an article the caller is allowed to modify, distinguishing 404 from 403. */
async function loadOwnedArticle(slug: string, userId: number) {
  const article = await prisma.article.findUnique({ where: { slug }, select: { id: true, authorId: true } })
  if (!article) throw notFound('article')
  if (article.authorId !== userId) throw forbidden('article')
  return article
}

/** Creates any missing tags and returns nested-write rows linking them to an article. */
async function connectTags(names: string[]) {
  if (names.length === 0) return []
  await prisma.tag.createMany({ data: names.map((name) => ({ name })), skipDuplicates: true })
  const tags = await prisma.tag.findMany({ where: { name: { in: names } }, select: { id: true } })
  return tags.map((tag) => ({ tagId: tag.id }))
}

export const articleRoutes: FastifyPluginAsync = async (app) => {
  // Feed must be registered as a literal path so it is never matched as a slug.
  app.get<{ Querystring: ListQuery }>(
    '/articles/feed',
    { preHandler: requireAuth },
    async (request) => {
      const userId = currentUserId(request)
      const where: Prisma.ArticleWhereInput = {
        author: { followers: { some: { followerId: userId } } },
      }
      return listArticles(where, request.query, userId)
    },
  )

  app.get<{ Querystring: ListQuery }>('/articles', async (request) => {
    const viewerId = request.auth?.id ?? ANONYMOUS
    const { tag, author, favorited } = request.query

    const where: Prisma.ArticleWhereInput = {
      ...(tag && { tags: { some: { tag: { name: tag } } } }),
      ...(author && { author: { username: author } }),
      ...(favorited && { favorites: { some: { user: { username: favorited } } } }),
    }

    return listArticles(where, request.query, viewerId)
  })

  app.get<{ Params: SlugParams }>('/articles/:slug', async (request) => {
    const viewerId = request.auth?.id ?? ANONYMOUS
    return { article: toArticle(await loadArticle(request.params.slug, viewerId), true) }
  })

  app.post('/articles', { preHandler: requireAuth }, async (request, reply) => {
    const userId = currentUserId(request)
    const input = envelope(request.body, 'article')
    const errors = new FieldErrors()

    const title = requiredString(input, 'title', errors)
    const description = requiredString(input, 'description', errors)
    const body = requiredString(input, 'body', errors)
    const tagList = optionalTagList(input, errors)
    errors.throwIfAny()

    const article = await prisma.article.create({
      data: {
        slug: slugify(title!),
        title: title!,
        description: description!,
        body: body!,
        authorId: userId,
        tags: { create: await connectTags(tagList.value) },
      },
      include: articleInclude(userId),
    })

    return reply.code(201).send({ article: toArticle(article, true) })
  })

  app.put<{ Params: SlugParams }>('/articles/:slug', { preHandler: requireAuth }, async (request) => {
    const userId = currentUserId(request)
    const existing = await loadOwnedArticle(request.params.slug, userId)

    const input = envelope(request.body, 'article')
    const errors = new FieldErrors()

    const title = optionalNonBlankString(input, 'title', errors)
    const description = optionalNonBlankString(input, 'description', errors)
    const body = optionalNonBlankString(input, 'body', errors)
    const tagList = optionalTagList(input, errors)
    errors.throwIfAny()

    // Replacing the tag set is a delete-then-create: an explicit `tagList` is
    // authoritative, while omitting the key leaves existing tags untouched.
    if (tagList.present) {
      await prisma.articleTag.deleteMany({ where: { articleId: existing.id } })
    }

    const article = await prisma.article.update({
      where: { id: existing.id },
      data: {
        ...(title !== undefined && { title, slug: slugify(title) }),
        ...(description !== undefined && { description }),
        ...(body !== undefined && { body }),
        ...(tagList.present && { tags: { create: await connectTags(tagList.value) } }),
      },
      include: articleInclude(userId),
    })

    return { article: toArticle(article, true) }
  })

  app.delete<{ Params: SlugParams }>(
    '/articles/:slug',
    { preHandler: requireAuth },
    async (request, reply) => {
      const existing = await loadOwnedArticle(request.params.slug, currentUserId(request))
      await prisma.article.delete({ where: { id: existing.id } })
      return reply.code(204).send()
    },
  )

  app.post<{ Params: SlugParams }>(
    '/articles/:slug/favorite',
    { preHandler: requireAuth },
    async (request) => setFavorite(request, true),
  )

  app.delete<{ Params: SlugParams }>(
    '/articles/:slug/favorite',
    { preHandler: requireAuth },
    async (request) => setFavorite(request, false),
  )
}

async function setFavorite(request: FastifyRequest<{ Params: SlugParams }>, favorited: boolean) {
  const userId = currentUserId(request)
  const article = await prisma.article.findUnique({
    where: { slug: request.params.slug },
    select: { id: true },
  })
  if (!article) throw notFound('article')

  if (favorited) {
    await prisma.favorite.upsert({
      where: { userId_articleId: { userId, articleId: article.id } },
      create: { userId, articleId: article.id },
      update: {},
    })
  } else {
    await prisma.favorite.deleteMany({ where: { userId, articleId: article.id } })
  }

  return { article: toArticle(await loadArticle(request.params.slug, userId), true) }
}

