import { ApiError } from './lib/errors.js'
import { authPlugin } from './plugins/auth.js'
import { articleRoutes } from './routes/articles.js'
import { commentRoutes } from './routes/comments.js'
import { profileRoutes } from './routes/profiles.js'
import { tagRoutes } from './routes/tags.js'
import { userRoutes } from './routes/users.js'

export async function buildServer(): Promise<FastifyInstance> {
  const app = Fastify({
    logger: process.env['NODE_ENV'] !== 'test',
    // Trailing slashes and casing should not change which route is matched.
    ignoreTrailingSlash: true,
    caseSensitive: false,
  })

  await app.register(authPlugin)

  await app.register(
    async (api) => {
      await api.register(userRoutes)
      await api.register(profileRoutes)
      await api.register(articleRoutes)
      await api.register(commentRoutes)
      await api.register(tagRoutes)
    },
    { prefix: '/api' },
  )

  app.get('/health', async () => ({ status: 'ok' }))

  // Every failure is reported in the RealWorld envelope: `{ "errors": { field: [...] } }`.
  app.setErrorHandler((error, request, reply) => {
    if (error instanceof ApiError) {
      return reply.code(error.statusCode).send({ errors: error.errors })
    }

    if (error.statusCode === 400) {
      return reply.code(422).send({ errors: { body: ['is invalid'] } })
    }

    request.log.error(error)
    return reply.code(500).send({ errors: { body: ['internal server error'] } })
  })

  app.setNotFoundHandler((_request, reply) =>
    reply.code(404).send({ errors: { route: ['not found'] } }),
  )

  return app
}

